// S4 Zusteller v2 (Phase 1a): neue Objekte der letzten 24 h, je Profil nach Vorscore sortiert. HTML fuer Telegram.
// Nur Felder aus der Tabelle, kein Modellaufruf, kein Abruf. Adresse ohne Hausnummer (R19). Grenze 4096 Zeichen -> Teile.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const eur = n => (typeof n === 'number') ? n.toLocaleString('de-DE') + ' €' : 'k. A.';
const zahl = (n, e) => (typeof n === 'number') ? n.toLocaleString('de-DE') + e : 'k. A.';
const PROFILNAME = { A: 'Profil A: Anlage-ETW', B: 'Profil B: Haus', unbekannt: 'Ohne Profil' };
const DECKEL = { unter_deckel: 'unter Deckel', verhandlungsfall: 'Verhandlungsfall', unter_deckel_notbehelf: 'unter Deckel (nur Angebotspreis)', unter_deckel_preis_fehlt: 'Preis fehlt, Referenz unter Deckel', kein_preis: 'Preis fehlt', ueber_deckel_angebotspreis: 'über Deckel (nur Angebotspreis, unvollständig)', ausgeschlossen_referenzpreis: 'ausgeschlossen (Deckel am Referenzpreis)', kein_profil: '' };

const rows = $input.all().map(i => i.json).filter(j => j && j.objekt_schluessel && String(j.objekt_schluessel).startsWith('is24:'));
const neu = rows;   // v3: Eingabe sind nur Objekte mit zustand = vorbewertet (noch nicht gemeldet); nach dem Senden werden sie 'gemeldet'
const ordnung = { A: 0, B: 1, unbekannt: 2 };
const deckelRang = { unter_deckel: 0, verhandlungsfall: 1, unter_deckel_notbehelf: 2, unter_deckel_preis_fehlt: 3, kein_preis: 3, ueber_deckel_angebotspreis: 4, ausgeschlossen_referenzpreis: 5 };   // E34 (10.09.2026): kaufbare zuerst, ueber Deckel bleibt sichtbar (R4)
const rang = j => deckelRang[j.deckel_status] ?? 4;
neu.sort((a, b) => (ordnung[a.profil ?? 'unbekannt'] - ordnung[b.profil ?? 'unbekannt']) || (rang(a) - rang(b)) || ((b.vorscore ?? -1) - (a.vorscore ?? -1)) || ((a.preis_je_qm || 0) - (b.preis_je_qm || 0)));

const datum = new Date().toLocaleDateString('de-DE', { timeZone: 'Europe/Berlin', weekday: 'short', day: '2-digit', month: '2-digit', year: 'numeric' });
const kopf = neu.length ? `<b>Immo-Digest ${esc(datum)}</b>\nNeu seit dem letzten Digest: ${neu.length}.\nVorscore aus Anzeigenfeldern und Referenzpreis (Immobilienrichtwert 2026), Belegdichte in Klammern. Kein Kaufurteil.` : `<b>Immo-Digest ${esc(datum)}</b>\nKeine neuen Objekte seit dem letzten Digest. Sammler und Buchhalter laufen.`;

const zeilen = [];
let letzter = null;
for (const j of neu) {
  const pr = j.profil ?? 'unbekannt';
  if (pr !== letzter) { zeilen.push(`\n<b>${esc(PROFILNAME[pr] || pr)}</b>`); letzter = pr; }
  const ort = [j.stadtteil, j.strasse].filter(x => x && x !== 'fehlt in der Anzeige').join(', ');
  const link = j.link ? `<a href="${esc(j.link)}">${esc(j.titel || j.objekt_schluessel)}</a>` : esc(j.titel || j.objekt_schluessel);
  const score = (typeof j.vorscore === 'number') ? `Vorscore ${j.vorscore} (${String(j.belegdichte ?? 0).replace('.', ',')})` : 'noch ohne Vorbewertung';
  const lage = j.lage_stufe === 'kernlage' ? 'Kernlage' : (j.lage_stufe === 'im_radius' ? 'im Radius' : '');
  const deckel = DECKEL[j.deckel_status] || '';
  const z2 = [score, lage, deckel].filter(Boolean).join(' | ');
  const refTeile = [];
  if (typeof j.referenz_qm === 'number') refTeile.push(`Referenz ${zahl(j.referenz_qm, ' €/m²')}` + (j.referenz_band ? ` (Band ${String(j.referenz_band).replace('-', ' bis ')})` : '') + (j.referenz_quelle === 'gmb_koeln_2026' ? ', Marktbericht' : ''));
  if (typeof j.preisabstand_pct === 'number') refTeile.push(`Abstand ${j.preisabstand_pct > 0 ? '+' : ''}${String(j.preisabstand_pct).replace('.', ',')} %`);
  if (typeof j.zielgebot_eur === 'number') refTeile.push(`Zielgebot ${eur(j.zielgebot_eur)}`);
  const z3 = refTeile.length ? `\n  ${esc(refTeile.join(' | '))}` : '';
  const anfrage = (typeof j.vorscore === 'number' && j.vorscore >= 55 && j.anfrage_status !== 'angefragt' && j.expose_id) ? `\n  Exposé anfragen: /e${j.expose_id}` : '';
  zeilen.push(`• ${link}\n  ${esc(ort || 'Lage k. A.')} | ${eur(j.kaufpreis_eur)} | ${zahl(j.wohnflaeche_qm, ' m²')} | ${zahl(j.zimmer, ' Zi.')} | ${zahl(j.preis_je_qm, ' €/m²')}${j.provision_kaeufer_pct === 0 ? ' | provisionsfrei' : ''}\n  ${esc(z2)}${typeof j.gesamtaufwand_eur === 'number' ? ' | Gesamtaufwand ' + eur(j.gesamtaufwand_eur) : ''}${z3}${anfrage}`);
}

const MAX = 3900;
const teile = [];
let akt = kopf;
for (const z of zeilen) {
  if ((akt + '\n' + z).length > MAX) { teile.push(akt); akt = z; } else { akt += '\n' + z; }
}
teile.push(akt);
return teile.map((text, i) => ({ json: { text, teil: i + 1, teile: teile.length, anzahl_neu: neu.length, anzahl_bestand: rows.length, schluessel: neu.map(j => j.objekt_schluessel) } }));

// Ein Item je gemeldetem Objekt, damit die Tabelle den Zustand fortschreibt (vorbewertet -> gemeldet)
const keys = $('Digest bauen').first().json.schluessel || [];
const jetzt = new Date().toISOString();
return keys.map(k => ({ json: { objekt_schluessel: k, zustand: 'gemeldet', gemeldet_am: jetzt } }));
